# ============================================================
# Helpers: routing mode, and joining traffic onto geometry
# ============================================================
# Three helpers used by every criticality analysis in this notebook.
#
# ------------------------------------------------------------------
# 1. ROUTING MODE - select_nearest_routes / od_table_single_destination
# ------------------------------------------------------------------
# AnalysisLossesEnum.OPTIMAL_ROUTE_ORIGIN_DESTINATION routes every origin
# to EVERY destination (a full cross product - see
# _get_origin_destination_pairs in RA2CE), and TrafficAnalysis then splits
# each origin's population evenly across them:
#     traffic = population / count_destination_nodes
# For the 7 basin exits that means each resident contributes 1/7 of a trip
# to all seven, including exits on the far side of the lake. Origin O_0's
# nearest exit is 6.4 km away and its furthest is 73.8 km; both receive the
# same share. Averaged over the basin it inflates mean trip length from
# 10.7 km to 37.6 km and total person-metres by 3.6x, loading long
# cross-basin corridors that nobody would actually drive.
#
# ROUTING_MODE = "nearest" gives each origin one route - to its closest
# destination - carrying its FULL population, which is what the Part 3
# heading has always described and what criticality for evacuation or
# emergency access means. No re-routing is needed: RA2CE already solved the
# optimal path to every destination, so the shortest of them IS the optimal
# path to the nearest one.
#
# ------------------------------------------------------------------
# 2. join_traffic_to_network
# ------------------------------------------------------------------
# TrafficAnalysis / EquityAnalysis key traffic by consecutive node pairs in
# opt_path, which are origins_destinations_graph node ids. Merging those
# straight onto base_network loses most of the result:
#
#   DIRECTION. opt_path pairs run in travel direction; the network stores
#   digitisation direction, which flips arbitrarily along a corridor. On one
#   10,586-edge run, 3,326 pairs matched (node_A, node_B) and 3,873 matched
#   only the reverse, so a forward-only merge drops the larger half - which
#   is what makes traffic alternate on/off along a single road. RA2CE also
#   emits (a,b) and (b,a) as separate rows, so the two directions have to be
#   summed rather than joined separately.
#
#   MISSING EDGES. Snapping origins and destinations splits edges and adds
#   new ones. Those exist in origins_destinations_graph_edges.gpkg but not
#   in base_network, so ~32% of routed edges have no base_network row at all.
#
#   STALE GRAPH. static/output_graph/ is rewritten by every RA2CE run, so
#   scores from one run joined against another run's graph match almost
#   nothing. The old code exported a near-empty file instead of failing.
#
# The fix: fold u/v onto an undirected key, join to
# origins_destinations_graph_edges.gpkg, then carry the score onto the
# original Overture geometry through rfid (base_network.rfid is the
# simplified edge each complex segment belongs to, exactly what
# complex_to_simple.json records).

def select_nearest_routes(od_gdf, length_col="length"):
    """One route per origin: the shortest, i.e. to its closest destination."""
    _r = od_gdf[od_gdf[length_col].notna()]
    _keep = _r.loc[_r.groupby("origin")[length_col].idxmin()]
    print(f"  nearest-destination routing: {len(_keep):,} routes kept "
          f"of {len(od_gdf):,} ({od_gdf['origin'].nunique():,} origins)")
    return _keep.copy()


def od_table_single_destination(od_table, d_col="d_id"):
    """
    Collapse the destination ids to one label.

    TrafficAnalysisBase divides every origin's population by
    len(unique(od_table[d_id])). In nearest-destination mode each origin has
    exactly one route and must contribute its FULL population to it, so the
    divisor has to be 1.
    """
    _t = od_table.copy()
    _mask = _t[d_col].notna()
    _t.loc[_mask, d_col] = "D_NEAREST"
    return _t


def join_traffic_to_network(traffic_frames, root_dir=None, graph_dir=None,
                            min_match_rate=0.99, on_mismatch="raise"):
    """
    Join TrafficAnalysis / EquityAnalysis scores onto the network geometry.

    Parameters
    ----------
    traffic_frames : dict
        {score_column: dataframe}, each the output of
        .optimal_route_od_link(), carrying u, v and that score column.
        A None value is skipped.
    root_dir : Path, optional
        Analysis root. Defaults to the notebook's ROOT_DIR.
    graph_dir : Path, optional
        Directory holding origins_destinations_graph_edges.gpkg and
        base_network.feather. Defaults to <root>/static/output_graph. Point
        this at an archived copy to recompute criticality for an older run
        without re-routing it.
    min_match_rate : float
        Fraction of routed edges that must exist in the graph before the
        result is trusted. Below this, scores and graph are from different runs.
    on_mismatch : {"raise", "warn"}

    Returns
    -------
    (net_scored, scored_edges, info)
    """
    from pathlib import Path
    import geopandas as gpd
    import pandas as pd
    import numpy as np

    _root = Path(root_dir) if root_dir is not None else ROOT_DIR
    _og = Path(graph_dir) if graph_dir is not None else _root / "static" / "output_graph"

    import ast as _ast

    def _undirected_key(u_vals, v_vals):
        return [tuple(sorted((int(a), int(b)))) for a, b in zip(u_vals, v_vals)]

    def _rfid_c_list(v):
        """The complex segment ids a graph edge covers (scalar or list-string)."""
        if isinstance(v, (list, tuple)):
            return [int(x) for x in v]
        if isinstance(v, str) and v.strip().startswith("["):
            return [int(x) for x in _ast.literal_eval(v)]
        try:
            return [int(v)]
        except (TypeError, ValueError):
            return []

    edges = gpd.read_file(_og / "origins_destinations_graph_edges.gpkg")
    edges["_k"] = _undirected_key(edges["u"], edges["v"])
    edge_keys = set(edges["_k"])

    # PARALLEL EDGES. opt_path is a list of NODES, so a route through a
    # multigraph tells us the node pair but not which of several parallel
    # edges was used. Folding on (u,v) therefore hands every parallel edge the
    # same traffic - a little loop beside a direct link reads exactly what the
    # link carries. Example: nodes 56219-56222 carry a 25 m direct edge
    # (key 0) and a 47 m three-segment loop (key 1); the loop was inheriting
    # the direct link's 6,780.
    #
    # Dijkstra on a MultiGraph uses the minimum-weight parallel edge, and the
    # analysis weighed on length, so only the shortest edge of each group can
    # be the one a route actually traversed. Ties are broken deterministically
    # (fewest constituent segments, then lowest rfid) rather than loading both.
    _grp = edges.groupby("_k")["length"]
    edges["_n_par"] = _grp.transform("size")
    edges["_min_len"] = _grp.transform("min")
    edges["_n_seg"] = [len(_rfid_c_list(v)) for v in edges["rfid_c"]]
    _tie = edges["length"] <= edges["_min_len"] + 1e-9
    edges["_rank"] = list(zip(~_tie, edges["_n_seg"], edges["rfid"]))
    edges["_carrier"] = edges.groupby("_k")["_rank"].transform("min") == edges["_rank"]
    _n_alt = int((~edges["_carrier"]).sum())
    if _n_alt:
        print(f"  {_n_alt:,} parallel alternative edges will not receive routed "
              f"traffic (only the shortest edge of each node pair can be on a route)")

    info = {}
    scored_edges = edges.copy()
    score_cols = []

    for col, tdf in traffic_frames.items():
        if tdf is None or col not in getattr(tdf, "columns", []):
            continue
        t = tdf[["u", "v", col]].copy()
        t["_k"] = _undirected_key(t["u"], t["v"])
        # (a,b) and (b,a) are the same physical link, so sum them.
        t = t.groupby("_k", as_index=False)[col].sum()

        rate = float(t["_k"].isin(edge_keys).mean()) if len(t) else 0.0
        info[col] = {"routed_edges": len(t), "match_rate": rate}
        if rate < min_match_rate:
            msg = (
                f"only {rate:.1%} of the {len(t):,} routed edges in '{col}' exist in "
                f"{_og}/origins_destinations_graph_edges.gpkg. static/output_graph/ is "
                f"rewritten by every RA2CE run, so these scores almost certainly belong "
                f"to a different run. Re-run the OD analysis, or pass graph_dir pointing "
                f"at the archived graph for this run."
            )
            if on_mismatch == "raise":
                raise ValueError(msg)
            print(f"  *** WARNING: {msg}")

        scored_edges = scored_edges.merge(t, on="_k", how="left")
        # a parallel alternative was never traversed, so it carries nothing
        scored_edges.loc[~scored_edges["_carrier"], col] = np.nan
        score_cols.append(col)

    if not score_cols:
        raise ValueError("No usable score frames were passed to join_traffic_to_network.")

    # Carry the score onto the original Overture segments.
    #
    # The key is rfid_c, NOT rfid. Every graph edge carries an explicit list of
    # the complex segment ids it covers (e.g. rfid_c = [32184, 8262]), and that
    # list is authoritative: it names exactly which Overture segments make up
    # the simplified edge.
    #
    # base_network.rfid cannot be used for this. It is assigned during the base
    # simplification, before origins and destinations are snapped in; that step
    # splits edges and renumbers them, so 236 rfid values in base_network have
    # no counterpart in the OD graph. Joining on rfid silently dropped 218-245
    # segments per analysis that a *traversed* graph edge explicitly named -
    # they came out as 0 in the middle of loaded corridors.
    #
    # A segment can be named by more than one graph edge (1,610 of them are,
    # up to 6 edges), so take the max rather than summing.
    base_net = gpd.read_feather(_og / "base_network.feather")
    _pairs = [(c, ei) for ei, v in zip(scored_edges.index, scored_edges["rfid_c"])
              for c in _rfid_c_list(v)]
    _map = pd.DataFrame(_pairs, columns=["rfid_c", "_ei"])
    _scores = _map.merge(scored_edges[score_cols], left_on="_ei", right_index=True)
    per_seg = _scores.dropna(subset=score_cols, how="all").groupby("rfid_c")[score_cols].max()

    _named = set(_map["rfid_c"])
    _missing = int((~base_net["rfid_c"].isin(_named)).sum())
    if _missing:
        print(f"  WARNING: {_missing:,} base_network segments are named by no graph "
              f"edge and cannot be scored")

    net_scored = base_net.copy()
    for col in score_cols:
        net_scored[col] = net_scored["rfid_c"].map(per_seg[col])

    # QA flag: segments that sit on a parallel alternative rather than on the
    # edge a route could have used. They are legitimately zero, but the flag
    # distinguishes "alternative link" from "simply not on any route".
    _alt_segs = set()
    for v, carrier in zip(scored_edges["rfid_c"], scored_edges["_carrier"]):
        if not carrier:
            _alt_segs.update(_rfid_c_list(v))
    _carrier_segs = set()
    for v, carrier in zip(scored_edges["rfid_c"], scored_edges["_carrier"]):
        if carrier:
            _carrier_segs.update(_rfid_c_list(v))
    net_scored["par_alt"] = net_scored["rfid_c"].isin(_alt_segs - _carrier_segs).astype(int)
    info["parallel_alt_segments"] = int(net_scored["par_alt"].sum())
    if info["parallel_alt_segments"]:
        print(f"  flagged par_alt=1 on {info['parallel_alt_segments']:,} segments "
              f"({net_scored.loc[net_scored['par_alt'] == 1, 'length'].sum():,.0f} m) "
              f"that lie only on parallel alternatives")

    # A segment no optimal route traverses carries zero population. That is a
    # measured value, not a missing one - "routed" keeps the distinction so
    # maps can grey out untravelled links.
    net_scored["routed"] = net_scored[score_cols].notna().any(axis=1)
    net_scored[score_cols] = net_scored[score_cols].fillna(0.0)
    scored_edges["routed"] = scored_edges[score_cols].notna().any(axis=1)
    scored_edges[score_cols] = scored_edges[score_cols].fillna(0.0)

    info["segments_routed"] = int(net_scored["routed"].sum())
    info["segments_total"] = len(net_scored)
    info["score_columns"] = score_cols

    for col in score_cols:
        _zero = int((net_scored["routed"] & (net_scored[col] == 0)).sum())
        print(f"  {col:22s}: {info[col]['routed_edges']:,} routed graph edges, "
              f"{info[col]['match_rate']:.1%} matched, {_zero:,} routed segments score 0")
    print(f"  {info['segments_routed']:,} of {info['segments_total']:,} network "
          f"segments carry routed traffic; the rest are set to 0")

    return net_scored, scored_edges, info


def archive_graph_files(dest_dir, root_dir=None):
    """
    Copy the two graph files criticality needs next to an analysis' output.

    static/output_graph/ is rebuilt by the next run, which is what makes an
    old analysis impossible to re-score without re-routing it. With these
    archived, join_traffic_to_network(graph_dir=...) can rebuild the
    criticality layers from the saved routes in seconds.
    """
    import shutil
    from pathlib import Path
    _root = Path(root_dir) if root_dir is not None else ROOT_DIR
    _src = _root / "static" / "output_graph"
    _dst = Path(dest_dir); _dst.mkdir(parents=True, exist_ok=True)
    for _name in ("origins_destinations_graph_edges.gpkg", "base_network.feather",
              "origin_destination_table.feather"):
        shutil.copy2(_src / _name, _dst / _name)
    print(f"  archived graph -> {_dst}")
    return _dst


# ------------------------------------------------------------------
# 3. accumulate_traffic - how an origin's population is split across
#    the destinations it was routed to
# ------------------------------------------------------------------
# RA2CE's TrafficAnalysis always divides an origin's population evenly by
# the destination count, which is only meaningful when every destination is
# equally plausible. Three modes are supported here instead:
#
#   "nearest" -- all of an origin's population on its single shortest route.
#                Right where the choice is forced: leaving the basin by the
#                closest exit, or the police station whose jurisdiction you
#                are in. Both of those have few near-ties (median 2nd-best
#                is 1.77x and 1.87x the nearest).
#
#   "gravity" -- population split across destinations in proportion to
#                1 / distance**beta, renormalised to 1. Needed where several
#                facilities are effectively co-located and "nearest" becomes
#                a coin flip: Barton Memorial and Tahoe Urgent Care are 600 m
#                apart, the two Incline Village medical facilities 1.2 km,
#                and 47% of origins have their 2nd-nearest medical facility
#                within 10% of the nearest. Winner-take-all hands one of each
#                pair the whole catchment and leaves the other's access roads
#                reading as unused. Gravity gives both a share, and distant
#                facilities a negligible one.
#
#   "all"      -- RA2CE's own behaviour, population split evenly regardless
#                of distance. Kept for comparison; it loads 70 km hauls as
#                heavily as the corridor next door.
#
# beta is the decay exponent (GRAVITY_BETA, default 2.0). The mode is a
# continuum: beta = 0 reproduces "all", and beta -> infinity reproduces
# "nearest", which is what makes the three comparable.
#
# Returns the same columns RA2CE's optimal_route_od_link() does, so
# join_traffic_to_network consumes it unchanged.

def accumulate_traffic(routes, population, mode="nearest", beta=None,
                       origin_weights=None, length_col="length",
                       origin_col="origin", min_distance=1.0):
    """
    Split each origin's population across its routes and sum onto edges.

    Parameters
    ----------
    routes : GeoDataFrame
        OD routes, with origin, opt_path and a length column. Every
        origin-destination pair, not a pre-filtered subset.
    population : dict or Series
        o_id -> population.
    mode : {"nearest", "gravity", "all"}
    beta : float, optional
        Gravity decay exponent. Defaults to GRAVITY_BETA.
    origin_weights : dict, optional
        o_id -> equity weight, for the prioritarian column. Absent means 1.0,
        which makes traffic_prioritarian equal to traffic.
    min_distance : float
        Floor on route length, so a destination sitting on top of an origin
        cannot produce a divide-by-zero.

    Returns
    -------
    DataFrame [u, v, traffic, traffic_egalitarian, traffic_prioritarian]
    """
    import ast
    from collections import defaultdict
    import numpy as np
    import pandas as pd

    _beta = float(beta if beta is not None else globals().get("GRAVITY_BETA", 2.0))
    if mode not in ("nearest", "gravity", "all"):
        raise ValueError(f"mode must be nearest/gravity/all, got {mode!r}")

    _pop = dict(population) if not isinstance(population, dict) else population
    _w = origin_weights or {}

    util = defaultdict(float)
    egal = defaultdict(float)
    prio = defaultdict(float)

    n_routes = n_origins = 0
    for o_id, grp in routes.groupby(origin_col, sort=False):
        pop = _pop.get(o_id)
        if pop is None or not np.isfinite(pop):
            continue
        d = np.asarray(grp[length_col], dtype="float64")
        d = np.clip(d, min_distance, None)

        if mode == "nearest":
            share = np.zeros(len(d)); share[int(np.argmin(d))] = 1.0
        elif mode == "all":
            share = np.full(len(d), 1.0 / len(d))
        else:
            inv = d ** (-_beta)
            tot = inv.sum()
            share = inv / tot if tot > 0 else np.full(len(d), 1.0 / len(d))

        wt = float(_w.get(o_id, 1.0))
        n_origins += 1
        for s, path in zip(share, grp["opt_path"]):
            if s <= 0:
                continue
            n_routes += 1
            p = ast.literal_eval(path) if isinstance(path, str) else path
            for a, b in zip(p[:-1], p[1:]):
                k = (str(a), str(b))
                util[k] += s * pop
                egal[k] += s
                prio[k] += s * pop * wt

    out = pd.DataFrame(
        [(u, v, util[(u, v)], egal[(u, v)], prio[(u, v)]) for (u, v) in util],
        columns=["u", "v", "traffic", "traffic_egalitarian", "traffic_prioritarian"],
    )
    print(f"  mode={mode}" + (f" beta={_beta:g}" if mode == "gravity" else "")
          + f": {n_origins:,} origins over {n_routes:,} weighted routes "
            f"-> {len(out):,} directed edges")
    return out


def resolve_routing_mode(analysis_name):
    """Per-analysis routing mode, falling back to the global ROUTING_MODE."""
    return ROUTING_MODE_BY_ANALYSIS.get(analysis_name, ROUTING_MODE)


def origin_population(origins_shp, count_field=None):
    """
    Rebuild the o_id -> population lookup RA2CE writes to
    origin_destination_table.feather.

    RA2CE assigns o_id by row order when it reads the origins file, so
    O_<i> is row i. Verified against the feather for all 2,201 origins.
    Lets an archived run be re-scored after static/output_graph/ has moved on.
    """
    import geopandas as gpd
    _f = count_field or ORIGINS_COUNT_FIELD
    g = gpd.read_file(origins_shp).reset_index(drop=True)
    return {f"O_{i}": float(v) for i, v in enumerate(g[_f].fillna(0))}




