# ============================================================
# OD Analysis Function
# ============================================================
# Wraps the OD analysis workflow into a reusable function.
# Accepts custom origin and destination feature class paths.
# Handles both shapefiles and GDB layers automatically.
#
# Usage:
#   run_od_analysis(
#       origins_fc_path="path/to/origins.shp",
#       destinations_fc_path="F:/data.gdb/LayerName",
#       analysis_name="my_od_analysis",
#       origin_count_field="POPULATION",
#   )

def run_od_analysis(
    origins_fc_path,
    destinations_fc_path,
    analysis_name="od_analysis",
    origin_count_field="POPULATION",
    equity_weight_field="",
    reuse_network_output=False,
    network_shapefile=None,
    run_criticality=True,
    equity_regions_shp=None,
    equity_weights_csv=None,
    routing_mode=None,
):
    """
    Execute OD analysis on custom origin/destination feature classes.
    
    Parameters
    ----------
    origins_fc_path : str or Path
        Path to origins feature class (shapefile or GDB layer).
        Formats: "/path/to/file.shp" or "/path/to/file.gdb/LayerName"
    destinations_fc_path : str or Path
        Path to destinations feature class (shapefile or GDB layer).
        Formats: "/path/to/file.shp" or "/path/to/file.gdb/LayerName"
    analysis_name : str
        Name for this analysis (used in output naming).
    origin_count_field : str
        Column name in origins layer containing population/count values.
        Default: "POPULATION".
    equity_weight_field : str
        Optional column name for per-origin equity weighting.
        If blank, only utilitarian analysis is run.
    reuse_network_output : bool
        If True, RA2CE reuses whatever is already in static/output_graph/ and
        IGNORES network_shapefile / primary_file entirely. It also skips
        rebuilding the origins-destinations graph, so a second call with
        different destinations would silently re-use the first call's OD graph.
        Leave this False unless the graph files are known to belong to this
        exact origins/destinations/network combination. Default: False.
    network_shapefile : Path or str, optional
        Path to network shapefile. If None, uses NETWORK_SHP from config.
    run_criticality : bool
        If True, also compute utilitarian and prioritarian (equity-weighted)
        link criticality for this destination set and export the scored
        network. Default: True.
    equity_regions_shp : Path or str, optional
        Region polygons carrying a region-name column, used to assign each
        origin to a region. Defaults to NETWORK_PATH / "blockgroup.shp".
    equity_weights_csv : Path or str, optional
        CSV with "region" and "weight" columns. Defaults to
        NETWORK_PATH / "blockgroup_weights.csv".
    routing_mode : {"nearest", "gravity", "all"}, optional
        How to split each origin's population across destinations. Defaults
        to ROUTING_MODE_BY_ANALYSIS[analysis_name], then ROUTING_MODE.
    
    Returns
    -------
    dict
        Results dictionary with keys:
        - "od_gdf": GeoDataFrame of routes
        - "od_table": OD table with population
        - "base_net": Base network with traffic scores
        - "config": Analysis configuration used
        - "exports": Paths to the written .gpkg / .shp, plus the columns
          dropped from the shapefile for exceeding the .dbf text limit
        - "net_scored": Base network with "traffic" (utilitarian) and
          "traffic_prioritarian" (equity-weighted) columns, or None if
          run_criticality was False or the inputs were unavailable
        - "criticality": Summary stats and export paths for the scored
          network, or None

    Side effects
    ------------
    Writes {analysis_name}_routes.gpkg and {analysis_name}_routes.shp next
    to RA2CE's own output, in output/optimal_route_origin_destination/.
    """
    from pathlib import Path
    import numpy as np
    import geopandas as gpd
    import pandas as pd
    from ra2ce.ra2ce_handler import Ra2ceHandler
    from ra2ce.network.network_config_data.network_config_data import (
        NetworkSection, NetworkConfigData, OriginsDestinationsSection,
    )
    from ra2ce.network.network_config_data.enums.source_enum import SourceEnum
    from ra2ce.analysis.analysis_config_data.analysis_config_data import (
        AnalysisSectionLosses, AnalysisConfigData,
    )
    from ra2ce.analysis.analysis_config_data.enums.analysis_losses_enum import AnalysisLossesEnum
    from ra2ce.analysis.analysis_config_data.enums.weighing_enum import WeighingEnum
    from ra2ce.analysis.losses.traffic_analysis.traffic_analysis import TrafficAnalysis
    from ra2ce.analysis.losses.traffic_analysis.equity_analysis import EquityAnalysis
    from pyproj import CRS
    
    def _read_geospatial_source(source_path):
        """
        Read feature class from shapefile or GDB layer.
        Handles both formats:
          - "/path/file.shp" -> shapefile
          - "/path/file.gdb/LayerName" -> GDB layer
        """
        source_str = str(source_path)
        if ".gdb" in source_str.lower():
            # GDB format: split on .gdb/
            parts = source_str.lower().split(".gdb")
            gdb_path = source_str[:len(parts[0]) + 4]  # Include .gdb
            layer_name = source_str[len(gdb_path)+1:]  # Everything after .gdb/
            print(f"  Reading from GDB: {gdb_path}")
            print(f"  Layer: {layer_name}")
            return gpd.read_file(gdb_path, layer=layer_name)
        else:
            # Shapefile or other format
            print(f"  Reading from: {source_path}")
            return gpd.read_file(source_path)
    
    # Resolve paths
    origins_path = Path(origins_fc_path)
    destinations_path = Path(destinations_fc_path)
    net_shp = Path(network_shapefile) if network_shapefile else NETWORK_SHP
    
    print(f"\n{'='*60}")
    print(f"Running OD Analysis: {analysis_name}")
    print(f"{'='*60}")
    print(f"Origins:      {origins_path}")
    print(f"Destinations: {destinations_path}")
    print(f"Network:      {net_shp}")
    print(f"{'='*60}\n")
    
    # Read origins and destinations using smart loader
    print("Loading origins...")
    origins_gdf = _read_geospatial_source(origins_path)
    print(f"  {len(origins_gdf):,} features | CRS: {origins_gdf.crs}")
    
    print("Loading destinations...")
    dests_gdf = _read_geospatial_source(destinations_path)
    print(f"  {len(dests_gdf):,} features | CRS: {dests_gdf.crs}")
    
    # Ensure both are in EPSG:4326
    if origins_gdf.crs is None or origins_gdf.crs.to_epsg() != 4326:
        print("  Reprojecting origins to EPSG:4326...")
        origins_gdf = origins_gdf.to_crs(4326)
    if dests_gdf.crs is None or dests_gdf.crs.to_epsg() != 4326:
        print("  Reprojecting destinations to EPSG:4326...")
        dests_gdf = dests_gdf.to_crs(4326)
    
    # Keep only Point geometries for destinations
    dests_gdf = dests_gdf[dests_gdf.geometry.geom_type == "Point"].copy().reset_index(drop=True)
    print(f"  Point features kept: {len(dests_gdf):,}")

    # ============================================================
    # Materialize the prepared OD inputs as shapefiles
    # ============================================================
    # RA2CE opens the origins/destinations paths itself, with a plain
    # gpd.read_file(path). That cannot open a File GDB feature class -
    # "<db>.gdb\LayerName" is not a path GDAL recognises, so passing the
    # GDB path straight through raises
    #   DataSourceError: ...gdb\LocalLawEnforcement: No such file or directory
    # even though _read_geospatial_source above read it fine.
    #
    # Writing the already-prepared GeoDataFrames out and pointing RA2CE at
    # those shapefiles fixes that, and also means the EPSG:4326
    # reprojection and the Point-only filter above actually reach RA2CE
    # instead of being discarded.
    if origin_count_field and origin_count_field not in origins_gdf.columns:
        print(f"  Warning: '{origin_count_field}' not in origins; adding it as 1 per origin")
        origins_gdf[origin_count_field] = 1

    od_origins_shp = NETWORK_PATH / f"{analysis_name}_origins.shp"
    od_dests_shp   = NETWORK_PATH / f"{analysis_name}_destinations.shp"
    origins_gdf.to_file(od_origins_shp)
    dests_gdf.to_file(od_dests_shp)
    print(f"  Prepared origins      -> {od_origins_shp.name}")
    print(f"  Prepared destinations -> {od_dests_shp.name}")

    # A shapefile .dbf truncates field names to 10 characters, which would
    # silently break the origin_count lookup inside RA2CE.
    if origin_count_field:
        written = gpd.read_file(od_origins_shp, rows=1)
        if origin_count_field not in written.columns:
            raise ValueError(
                f"origin_count field '{origin_count_field}' did not survive the "
                f"shapefile write (10-char .dbf limit). Rename it to <=10 chars "
                f"in the source layer. Written columns: {list(written.columns)}"
            )

    
    # Configure network
    #
    # reuse_network_output=True makes NetworkConfigWrapper load the existing
    # static/output_graph/ and never look at primary_file:
    #     if reuse_network_output:  graph_files = read_graphs_from_config(dir)
    #     else:                     shutil.rmtree(dir)
    # and Network.create() then skips the OD graph too, because
    #     if origins and destinations and not origins_destinations_graph.file
    # is already satisfied. So reusing here silently routes on whichever
    # network and destination set happened to be built last. Default False.
    network_section = NetworkSection(
        source=SourceEnum.SHAPEFILE,
        primary_file=net_shp,
        save_gpkg=True,
        reuse_network_output=reuse_network_output,
    )
    print(f"Network graph: {'REUSING static/output_graph' if reuse_network_output else 'rebuilding from ' + net_shp.name}")
    
    # Configure OD section
    od_section = OriginsDestinationsSection(
        origins=od_origins_shp,
        destinations=od_dests_shp,
        origin_count=origin_count_field,
    )
    
    # Build network config
    network_config = NetworkConfigData(
        root_path=ROOT_DIR,
        static_path=ROOT_DIR / "static",
        crs=CRS.from_epsg(4326),
        network=network_section,
        origins_destinations=od_section,
    )
    
    # Configure analysis
    od_analysis_config = AnalysisSectionLosses(
        name=analysis_name,
        analysis=AnalysisLossesEnum.OPTIMAL_ROUTE_ORIGIN_DESTINATION,
        weighing=WeighingEnum.LENGTH,
        calculate_route_without_disruption=True,
        save_csv=True,
        save_gpkg=True,
    )
    
    analysis_config = AnalysisConfigData(
        output_path=OUTPUT_PATH,
        static_path=ROOT_DIR / "static",
        analyses=[od_analysis_config],
    )
    
    # Run RA2CE
    print("Configuring RA2CE handler...")
    handler = Ra2ceHandler.from_config(network=network_config, analysis=analysis_config)
    handler.configure()
    print("Running analysis...")
    handler.run_analysis()
    
    # Load results
    print("\nLoading results...")
    od_gpkg_path = OUTPUT_PATH / "optimal_route_origin_destination" / f"{analysis_name}.gpkg"
    if not od_gpkg_path.exists():
        raise FileNotFoundError(f"Expected output not found: {od_gpkg_path}")
    
    od_gdf_result = gpd.read_file(od_gpkg_path)
    print(f"OD routes: {len(od_gdf_result):,}")

    # ============================================================
    # Export routes for ArcGIS Pro (GeoPackage + Shapefile)
    # ============================================================
    # RA2CE writes its own .gpkg above, but it carries list-typed columns
    # and an empty-named column that breaks ArcGIS Pro's SQL tokenizer.
    # These exports are re-typed to plain scalars.
    #
    # opt_path / match_ids are node and edge id lists up to ~4,000
    # characters long. A .dbf caps text at 254 and truncates silently,
    # leaving a half-written list that still looks like a valid value, so
    # over-long columns are dropped from the shapefile and kept in full in
    # the GeoPackage.
    export_dir = od_gpkg_path.parent
    DBF_TEXT_LIMIT = 254

    def _to_str(v):
        if v is None:
            return ""
        try:
            if isinstance(v, float) and np.isnan(v):
                return ""
        except (TypeError, ValueError):
            pass
        if isinstance(v, (list, tuple, np.ndarray)):
            return "|".join(str(x) for x in v)
        if isinstance(v, bytes):
            return v.decode("utf-8", errors="replace")
        return str(v)

    od_clean = od_gdf_result.copy()
    for col in od_clean.columns:
        if col == od_clean.geometry.name:
            continue
        s = od_clean[col]
        if s.dtype.kind == "f":
            od_clean[col] = s.astype("float64")
        elif s.dtype.kind in ("i", "u"):
            od_clean[col] = s.astype("int64")
        else:
            od_clean[col] = s.apply(_to_str)

    print("\nExporting routes...")
    out_gpkg = export_dir / f"{analysis_name}_routes.gpkg"
    out_gpkg.unlink(missing_ok=True)
    od_clean.to_file(out_gpkg, driver="GPKG", layer=f"{analysis_name}_routes")
    print(f"  GeoPackage: {out_gpkg.resolve()}")

    too_long = [
        c for c in od_clean.columns
        if c != od_clean.geometry.name
        and od_clean[c].dtype.kind == "O"
        and od_clean[c].str.len().max() > DBF_TEXT_LIMIT
    ]
    od_shp_ready = od_clean.drop(columns=too_long)
    if too_long:
        print(f"  Dropped from shapefile (over the {DBF_TEXT_LIMIT}-char .dbf limit): "
              f"{', '.join(too_long)} -- kept in full in the GeoPackage")

    out_shp = export_dir / f"{analysis_name}_routes.shp"
    od_shp_ready.to_file(out_shp)
    print(f"  Shapefile:  {out_shp.resolve()}")
    print("  (field names over 10 chars are truncated in the .dbf, "
          "e.g. destination -> destinatio)")
    
    # Load OD table if available
    od_table_path = ROOT_DIR / "static" / "output_graph" / "origin_destination_table.feather"
    if od_table_path.exists():
        od_table = pd.read_feather(od_table_path)
        print(f"OD table: {len(od_table):,} rows")
    else:
        od_table = None
        print("Warning: OD table feather not found")
    
    # Load base network if available
    base_net_path = ROOT_DIR / "static" / "output_graph" / "base_network.feather"
    if base_net_path.exists():
        base_net = gpd.read_feather(base_net_path)
        print(f"Base network: {len(base_net):,} edges")
    else:
        base_net = None
        print("Warning: Base network feather not found")

    # ============================================================
    # Link criticality: utilitarian + prioritarian (equity-weighted)
    # ============================================================
    # Utilitarian  -- segment score = sum of (origin population / n dests)
    #                 over every origin whose optimal route uses it.
    # Prioritarian -- the same, with each origin's population multiplied by
    #                 its region's equity weight (0-1), so links serving
    #                 higher-need areas rank higher.
    #
    # Both run on the origin-level OD table. Each origin is tagged with the
    # region it falls in and EquityAnalysis applies that region's weight
    # row-wise; see the note above the EquityAnalysis call for why the table
    # must not be aggregated to one row per region.
    net_scored = None
    criticality = None

    if not run_criticality:
        print("\nSkipping criticality (run_criticality=False)")
    elif od_table is None or base_net is None:
        print("\nSkipping criticality: OD table or base network unavailable")
    elif not {"origin", "opt_path"}.issubset(od_gdf_result.columns):
        print("\nSkipping criticality: routes lack 'origin'/'opt_path' columns")
    else:
        regions_shp = Path(equity_regions_shp) if equity_regions_shp else NETWORK_PATH / "blockgroup.shp"
        weights_csv = Path(equity_weights_csv) if equity_weights_csv else NETWORK_PATH / "blockgroup_weights.csv"

        print(f"\n{'-'*60}")
        print("Link criticality")
        print(f"{'-'*60}")

        # -- utilitarian ------------------------------------------------
        # TrafficAnalysis hardcodes "values" as the population column.
        od_table_ta = od_table.rename(columns={origin_count_field: "values"})
        total_pop = float(od_table_ta["values"].sum())
        _pop_by_origin = od_table.set_index("o_id")[origin_count_field].to_dict()
        _mode = routing_mode or resolve_routing_mode(analysis_name)
        print(f"Routing mode: {_mode}")
        traffic_df = accumulate_traffic(od_gdf_result, population=_pop_by_origin,
                                        mode=_mode)
        print(f"Utilitarian : {len(traffic_df):,} edges, "
              f"range {traffic_df['traffic'].min():.2f} -- {traffic_df['traffic'].max():.2f} "
              f"(total population {total_pop:,.0f})")

        # -- prioritarian ------------------------------------------------
        traffic_eq_df = None
        if not (regions_shp.exists() and weights_csv.exists()):
            print(f"Prioritarian: skipped -- missing {regions_shp.name} "
                  f"and/or {weights_csv.name}")
        else:
            equity_data = pd.read_csv(weights_csv)
            regions_gdf = gpd.read_file(regions_shp)
            region_col = next(
                (c for c in regions_gdf.columns
                 if "region" in c.lower() and c != regions_gdf.geometry.name),
                None,
            )
            if region_col is None:
                print(f"Prioritarian: skipped -- no region-name column in {regions_shp.name}")
            else:
                # Map each origin to a region. Read the *prepared* origins
                # file, not the source layer, so the positional index lines
                # up with the O_<i> ids RA2CE assigned when it read them.
                prepared_origins = gpd.read_file(od_origins_shp)
                if prepared_origins.crs != regions_gdf.crs:
                    regions_gdf = regions_gdf.to_crs(prepared_origins.crs)

                sj = gpd.sjoin(
                    prepared_origins[[prepared_origins.geometry.name]],
                    regions_gdf[[region_col, regions_gdf.geometry.name]],
                    how="left", predicate="within",
                )
                # An origin on a shared region boundary can match twice;
                # keep the first so the o_id -> region map stays 1:1.
                sj = sj[~sj.index.duplicated(keep="first")]
                o_id_to_region = {
                    f"O_{i}": str(r) for i, r in sj[region_col].items() if pd.notna(r)
                }
                print(f"Origins mapped to regions: {len(o_id_to_region):,} / "
                      f"{len(prepared_origins):,}")

                od_eq = od_table_ta.copy()
                od_eq["region"] = od_eq["o_id"].map(o_id_to_region)
                matched = od_eq["region"].notna().sum()
                if matched == 0:
                    print("Prioritarian: skipped -- no OD rows matched a region "
                          f"(o_id samples: {list(od_eq['o_id'].head(3))})")
                else:
                    print(f"OD rows with a region: {matched:,} / {len(od_eq):,}")

                    # The table stays at ORIGIN level. EquityAnalysis looks each
                    # route's origin up with
                    #     od_table.loc[od_table["o_id"] == origin_node, col].values[0]
                    # where origin_node is the route's "origin" value ("O_0", ...),
                    # and computes values_prioritarian row-wise as
                    #     region -> weight  x  values
                    # So "region" only has to be a *column*; aggregating to one row
                    # per region and setting o_id = region name makes every lookup
                    # miss and raises IndexError on the first origin. The table also
                    # has to keep its "d_id" column, because the base class counts
                    # destinations with od_table["d_id"] before scoring anything.
                    weighted_regions = set(equity_data["region"])
                    od_eq["region"] = od_eq["region"].where(
                        od_eq["region"].isin(weighted_regions), "Not assigned"
                    )
                    n_unassigned = int((od_eq["region"] == "Not assigned").sum())
                    if n_unassigned:
                        print(f"  {n_unassigned:,} of {len(od_eq):,} rows have no "
                              f"region weight -> 'Not assigned', which RA2CE scores "
                              f"at weight 1.0")

                    _wt_by_region = dict(zip(equity_data["region"],
                                             equity_data["weight"]))
                    _origin_wt = {
                        o: float(_wt_by_region.get(r, 1.0))
                        for o, r in zip(od_eq["o_id"], od_eq["region"])
                    }
                    traffic_eq_df = accumulate_traffic(
                        od_gdf_result, population=_pop_by_origin,
                        mode=_mode, origin_weights=_origin_wt,
                    )

                    col = "traffic_prioritarian"
                    n_inf = int(traffic_eq_df[col].isin([np.inf, -np.inf]).sum())
                    if n_inf:
                        print(f"  Replaced {n_inf:,} infinite prioritarian values with 0")
                        traffic_eq_df[col] = traffic_eq_df[col].replace([np.inf, -np.inf], 0)
                    traffic_eq_df[col] = traffic_eq_df[col].fillna(0)
                    print(f"Prioritarian: {int((traffic_eq_df[col] > 0).sum()):,} edges "
                          f"non-zero, range {traffic_eq_df[col].min():.2f} -- "
                          f"{traffic_eq_df[col].max():.2f}")

        # -- join both score sets onto the network geometry ---------------
        # The scores are keyed by origins_destinations_graph node ids, so
        # they go through join_traffic_to_network (Part 1) instead of a
        # direct merge onto base_network. That helper folds the two travel
        # directions together and raises when static/output_graph/ no longer
        # belongs to this run - the old merge could not tell the difference
        # and simply exported a near-empty file.
        print("\nJoining scores to network geometry:")
        net_scored, scored_edges, join_info = join_traffic_to_network(
            {
                "traffic": traffic_df,
                "traffic_egalitarian": traffic_df,
                "traffic_prioritarian": traffic_eq_df,
            },
            root_dir=ROOT_DIR,
        )

        n_util = int((net_scored["traffic"] > 0).sum())
        n_prio = (int((net_scored["traffic_prioritarian"] > 0).sum())
                  if "traffic_prioritarian" in net_scored.columns else 0)
        join_rate = join_info["traffic"]["match_rate"]
        n_routed = join_info["segments_routed"]
        n_unrouted = join_info["segments_total"] - n_routed
        print(f"Segments with traffic: {n_util:,} utilitarian, "
              f"{n_prio:,} prioritarian (of {len(net_scored):,})")

        # static/output_graph/ is rebuilt by the next run, which is what makes
        # an older analysis impossible to re-score without repeating the
        # routing. Keep the two files criticality needs beside its output.
        archive_graph_files(export_dir / f"{analysis_name}_graph", root_dir=ROOT_DIR)

        crit_gpkg = export_dir / f"{analysis_name}_criticality.gpkg"
        crit_shp = export_dir / f"{analysis_name}_criticality.shp"
        crit_out = net_scored.copy()
        for c in crit_out.columns:
            if c == crit_out.geometry.name:
                continue
            s = crit_out[c]
            if s.dtype == bool:
                crit_out[c] = s.astype("int64")
            elif s.dtype.kind == "f":
                crit_out[c] = s.astype("float64")
            elif s.dtype.kind in ("i", "u"):
                crit_out[c] = s.astype("int64")
            else:
                crit_out[c] = s.apply(_to_str)
        # An unnamed column comes through from RA2CE's base_network and
        # is what breaks ArcGIS Pro's SQL parser on the .gpkg.
        crit_out = crit_out.rename(
            columns={c: "unnamed" for c in crit_out.columns if str(c).strip() == ""}
        )
        crit_gpkg.unlink(missing_ok=True)
        crit_out.to_file(crit_gpkg, driver="GPKG", layer=f"{analysis_name}_criticality")
        crit_out.to_file(crit_shp)
        print(f"  GeoPackage: {crit_gpkg.resolve()}")
        print(f"  Shapefile:  {crit_shp.resolve()}")

        criticality = {
            "gpkg": crit_gpkg,
            "shp": crit_shp,
            "edges_utilitarian": n_util,
            "edges_prioritarian": n_prio,
            "scored_edges": join_info["traffic"]["routed_edges"],
            "join_rate": join_rate,
            "edges_with_traffic": n_routed,
            "edges_without_traffic": n_unrouted,
            "total_population": total_pop,
            "regions_shp": regions_shp,
            "weights_csv": weights_csv,
        }
    
    results = {
        "od_gdf": od_gdf_result,
        "od_table": od_table,
        "base_net": base_net,
        "net_scored": net_scored,
        "criticality": criticality,
        "exports": {
            "gpkg": out_gpkg,
            "shp": out_shp,
            "shp_dropped_columns": too_long,
        },
        "config": {
            "analysis_name": analysis_name,
            "origins": str(origins_path),
            "destinations": str(destinations_path),
            "origin_count_field": origin_count_field,
            "prepared_origins": od_origins_shp,
            "prepared_destinations": od_dests_shp,
            "equity_weight_field": equity_weight_field,
        },
    }
    
    print(f"\n{'='*60}")
    print(f"Analysis complete: {analysis_name}")
    print(f"{'='*60}\n")
    
    return results


