#
# results_dict = {}
# for dest_name, dest_fc in destination_fcs.items():
#     print(f"\nRunning OD analysis for destination: {dest_name}")
#     result = run_od_analysis(
#         origins_fc_path=origin_featureclass,
#         destinations_fc_path=dest_fc,
#         analysis_name=f"tahoe_od_{dest_name}",
#         origin_count_field="POPULATION",
#     )
#     results_dict[dest_name] = result
